O] New tutor message","body":"Your demo tutor shared a practice update.","data":{"demo_dataset":"aerogen-live-demo-v1","conversationId":"35b1488f-ae21-5e74-8e1c-1d71517f8d2a"},"read_at":null,"created_at":"2026-10-27T16:00:00.000Z"},{"id":"8b3de671-8eeb-5b94-ae3a-833d5ed282b1","user_id":"de000000-0000-4000-8000-000000000201","kind":"booking","title":"[DEMO] Session history available","body":"A completed demo lesson is available for reviewing reports.","data":{"demo_dataset":"aerogen-live-demo-v1","bookingId":"8edbbcb6-6e98-5fdc-8493-6834ae8e9d87"},"read_at":"2026-10-28T06:00:00.000Z","created_at":"2026-10-26T10:00:00.000Z"},{"id":"d8142ad2-c5b3-57c7-83f3-2f12bb0d7e9d","user_id":"de000000-0000-4000-8000-000000000102","kind":"message","title":"[DEMO] New tutor message","body":"Your demo tutor shared a practice update.","data":{"demo_dataset":"aerogen-live-demo-v1","conversationId":"67521cba-93d1-590b-a922-b6ee7bd403ea"},"read_at":null,"created_at":"2026-10-27T16:00:00.000Z"},{"id":"a7cd1dee-01f9-5d63-8f14-111599b8ced1","user_id":"de000000-0000-4000-8000-000000000202","kind":"booking","title":"[DEMO] Session history available","body":"A completed demo lesson is available for reviewing reports.","data":{"demo_dataset":"aerogen-live-demo-v1","bookingId":"07cc60e7-aa8e-51b8-98da-6fe5f32bf7eb"},"read_at":null,"created_at":"2026-10-26T10:00:00.000Z"},{"id":"a53c8cca-984b-5da1-847a-a2555b6523fd","user_id":"de000000-0000-4000-8000-000000000103","kind":"message","title":"[DEMO] New tutor message","body":"Your demo tutor shared a practice update.","data":{"demo_dataset":"aerogen-live-demo-v1","conversationId":"d47d2c43-36f7-54f5-a9d6-b7508ba51b5f"},"read_at":null,"created_at":"2026-10-27T16:00:00.000Z"},{"id":"dd0325d1-9d01-56b4-90f3-b18d56caed8c","user_id":"de000000-0000-4000-8000-000000000204","kind":"booking","title":"[DEMO] Session history available","body":"A completed demo lesson is available for reviewing reports.","data":{"demo_dataset":"aerogen-live-demo-v1","bookingId":"4e5f2e60-fe89-594a-a0ae-7ff3c8907433"},"read_at":"2026-10-28T06:00:00.000Z","created_at":"2026-10-26T10:00:00.000Z"},{"id":"3aede388-6b10-5da0-a543-ce0a053308ca","user_id":"de000000-0000-4000-8000-000000000104","kind":"message","title":"[DEMO] New tutor message","body":"Your demo tutor shared a practice update.","data":{"demo_dataset":"aerogen-live-demo-v1","conversationId":"a8ecf5aa-39af-56d7-9b71-8ce9db290a7a"},"read_at":null,"created_at":"2026-10-27T16:00:00.000Z"},{"id":"b6b74a98-4512-52e5-8273-e3ea438385ea","user_id":"de000000-0000-4000-8000-000000000201","kind":"booking","title":"[DEMO] Session history available","body":"A completed demo lesson is available for reviewing reports.","data":{"demo_dataset":"aerogen-live-demo-v1","bookingId":"b3782037-f4da-5ad9-a036-f7a7b9aae91d"},"read_at":null,"created_at":"2026-10-26T10:00:00.000Z"},{"id":"7698ae18-5b72-5c30-bfcb-f718283d3744","user_id":"de000000-0000-4000-8000-000000000205","kind":"application","title":"[DEMO] Application under review","body":"This fictional tutor application is awaiting review.","data":{"demo_dataset":"aerogen-live-demo-v1","applicationId":"730a27bf-2c57-5d8f-8d67-a2e7bcad935d"},"read_at":null,"created_at":"2026-10-27T10:00:00.000Z"}]}'::jsonb);
do $$
declare a record; passwords jsonb := nullif(current_setting('aerogen.demo_passwords', true), '')::jsonb;
begin
  if passwords is null then raise exception 'Supply the private demo password map before seeding'; end if;
  for a in select * from jsonb_to_recordset((select data->'accounts' from aerogen_demo_fixture))
    as a(id uuid,key text,email text,"firstName" text,"lastName" text,role text,location text,scenario text)
  loop
    if a.email not like 'demo.%@example.test' or a.role not in ('student','tutor') then raise exception 'Invalid demo account definition'; end if;
    if length(coalesce(passwords->>a.id::text,'')) not between 20 and 72 then raise exception 'Missing strong demo password for %', a.key; end if;
    if exists (select 1 from auth.users u where (u.id=a.id or lower(u.email)=lower(a.email))
      and (u.id<>a.id or u.email<>a.email or u.raw_app_meta_data->>'demo_dataset' is distinct from 'aerogen-live-demo-v1')) then
      raise exception 'Refusing to overwrite an existing non-demo account: %', a.key;
    end if;
    if not exists (select 1 from auth.users u where u.id=a.id) then
      insert into auth.users (instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,
        confirmation_token,recovery_token,email_change_token_new,email_change,is_super_admin,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
      values ('00000000-0000-0000-0000-000000000000',a.id,'authenticated','authenticated',a.email,
        extensions.crypt(passwords->>a.id::text,extensions.gen_salt('bf',10)),now(),
        '','','','',false,
        jsonb_build_object('provider','email','providers',jsonb_build_array('email'),'demo_dataset','aerogen-live-demo-v1'),
        jsonb_build_object('firstName',a."firstName",'lastName',a."lastName",'role',a.role,'location',a.location,'demo_scenario',a.scenario),now()-interval '30 days',now());
    end if;
    insert into auth.identities (id,provider_id,user_id,identity_data,provider,created_at,updated_at)
    values (a.id,a.id::text,a.id,jsonb_build_object('sub',a.id::text,'email',a.email,'email_verified',true,'phone_verified',false),'email',now(),now()) on conflict do nothing;
    if not exists(select 1 from public.profiles p where p.id=a.id and p.role=a.role) then raise exception 'Demo profile role mismatch: %', a.key; end if;
    update public.profiles set demo_dataset='aerogen-live-demo-v1' where id=a.id and (demo_dataset is null or demo_dataset='aerogen-live-demo-v1');
    if not exists(select 1 from public.profiles p where p.id=a.id and p.demo_dataset='aerogen-live-demo-v1') then raise exception 'Demo marker mismatch: %',a.key; end if;
  end loop;
  if exists(select 1 from jsonb_array_elements((select data->'tutors' from aerogen_demo_fixture)) t,
    jsonb_array_elements_text(t->'subjects') subject where not exists(select 1 from public.subjects s where s.name=subject and s.is_active)) then raise exception 'Required demo subject is missing'; end if;
end $$;

insert into public.tutor_profiles (user_id,public_name,bio,city,province,qualification,institution,year_completed,years_experience,teaching_style,student_age_groups,availability_slots,teaching_modes,hourly_rate,students_per_session,is_approved,is_accepting_students,demo_dataset)
select id,public_name,bio,location,province,qualification,'DEMO Institution',2020,years,'[DEMO] Explain, practise, and check understanding.',
  array['Primary school','High school','College','University'],array['Weekday Afternoons','Weekday Evenings'],array['online','in-person'],rate,'1',approved,approved,'aerogen-live-demo-v1'
from jsonb_to_recordset((select data->'tutors' from aerogen_demo_fixture)) as t(id uuid,public_name text,bio text,location text,province text,qualification text,years numeric,rate numeric,approved boolean)
on conflict (user_id) do nothing;

insert into public.tutor_applications (id,user_id,status,city,province,highest_qualification,institution,year_completed,years_experience,student_age_groups,teaching_style,availability_slots,teaching_modes,hourly_rate,students_per_session,submitted_at,reviewed_at,review_notes)
select application_id,id,case when approved then 'approved' else 'submitted' end,location,province,qualification,'DEMO Institution',2020,years,
  array['Primary school','High school','College','University'],'[DEMO] Structured practice.',array['Weekday Afternoons','Weekday Evenings'],array['online','in-person'],rate,'1',now()-interval '14 days',case when approved then now()-interval '13 days' else null end,
  '[DEMO aerogen-live-demo-v1] Fictional application. No real identity documents or qualifications are uploaded.'
from jsonb_to_recordset((select data->'tutors' from aerogen_demo_fixture)) as t(id uuid,application_id uuid,location text,province text,qualification text,years numeric,rate numeric,approved boolean)
on conflict (id) do nothing;

insert into public.tutor_subjects (tutor_id,subject_id)
select (t->>'id')::uuid,s.id from jsonb_array_elements((select data->'tutors' from aerogen_demo_fixture)) t,
  jsonb_array_elements_text(t->'subjects') subject join public.subjects s on s.name=subject on conflict do nothing;
insert into public.tutor_application_subjects (application_id,subject_id)
select (t->>'application_id')::uuid,s.id from jsonb_array_elements((select data->'tutors' from aerogen_demo_fixture)) t,
  jsonb_array_elements_text(t->'subjects') subject join public.subjects s on s.name=subject on conflict do nothing;

insert into public.bookings (id,student_id,tutor_id,subject_id,starts_at,ends_at,timezone,status,teaching_mode,session_type,duration_minutes,hourly_rate,total_amount,currency,special_requests,created_at)
select b.id,b.student_id,b.tutor_id,s.id,b.starts_at,b.ends_at,'Africa/Johannesburg',b.status,b.teaching_mode,'individual',b.duration_minutes,b.hourly_rate,b.total_amount,'ZAR',b.special_requests,b.created_at
from jsonb_to_recordset((select data->'bookings' from aerogen_demo_fixture)) as b(id uuid,student_id uuid,tutor_id uuid,subject text,starts_at timestamptz,ends_at timestamptz,status text,teaching_mode text,duration_minutes smallint,hourly_rate numeric,total_amount numeric,special_requests text,created_at timestamptz)
join public.subjects s on s.name=b.subject on conflict (id) do nothing;

insert into public.payments (id,booking_id,payer_id,payee_id,provider,provider_reference,status,amount,platform_fee,currency,paid_at,created_at)
select id,booking_id,payer_id,payee_id,provider,provider_reference,status,amount,platform_fee,'ZAR',paid_at,created_at
from jsonb_to_recordset((select data->'payments' from aerogen_demo_fixture)) as p(id uuid,booking_id uuid,payer_id uuid,payee_id uuid,provider text,provider_reference text,status text,amount numeric,platform_fee numeric,paid_at timestamptz,created_at timestamptz)
on conflict (id) do nothing;
insert into public.reviews (id,booking_id,student_id,tutor_id,rating,body,is_published,created_at)
select id,booking_id,student_id,tutor_id,rating,body,true,created_at
from jsonb_to_recordset((select data->'reviews' from aerogen_demo_fixture)) as r(id uuid,booking_id uuid,student_id uuid,tutor_id uuid,rating smallint,body text,created_at timestamptz)
on conflict (id) do nothing;

insert into public.conversations (id,booking_id,created_by,created_at)
select id,booking_id,created_by,created_at from jsonb_to_recordset((select data->'conversations' from aerogen_demo_fixture)) as c(id uuid,booking_id uuid,created_by uuid,created_at timestamptz) on conflict (id) do nothing;
insert into public.conversation_members (conversation_id,user_id,last_read_at)
select c.id,m.user_id,m.last_read_at from jsonb_to_recordset((select data->'conversations' from aerogen_demo_fixture)) as c(id uuid,student_id uuid,tutor_id uuid,student_read_at timestamptz,tutor_read_at timestamptz)
cross join lateral (values(c.student_id,c.student_read_at),(c.tutor_id,c.tutor_read_at)) m(user_id,last_read_at) on conflict do nothing;
insert into public.messages (id,conversation_id,sender_id,body,created_at)
select id,conversation_id,sender_id,body,created_at from jsonb_to_recordset((select data->'messages' from aerogen_demo_fixture)) as m(id uuid,conversation_id uuid,sender_id uuid,body text,created_at timestamptz) on conflict (id) do nothing;
insert into public.notifications (id,user_id,kind,title,body,data,read_at,created_at)
select id,user_id,kind,title,body,data,read_at,created_at from jsonb_to_recordset((select data->'notifications' from aerogen_demo_fixture)) as n(id uuid,user_id uuid,kind text,title text,body text,data jsonb,read_at timestamptz,created_at timestamptz) on conflict (id) do nothing;
insert into public.user_notification_preferences (user_id,email_messages,email_booking_updates,email_payment_updates,push_messages,push_booking_updates,push_payment_updates)
select (a->>'id')::uuid,false,false,false,false,false,false from jsonb_array_elements((select data->'accounts' from aerogen_demo_fixture)) a on conflict (user_id) do nothing;
